import pytest
from candidate import sort_third

def test_sort_third_with_simple_list():
    assert sort_third([1, 2, 3]) == [1, 2, 3]

def test_sort_third_reorders_every_third_index():
    assert sort_third([5, 6, 3, 4, 8, 9, 2]) == [2, 6, 3, 4, 8, 9, 5]

def test_sort_third_empty_list_returns_empty():
    assert sort_third([]) == []

def test_sort_third_single_element_list():
    assert sort_third([42]) == [42]

def test_sort_third_two_elements_list_unchanged():
    assert sort_third([2, 1]) == [2, 1]

def test_sort_third_four_elements_reorder_indices_0_and_3():
    assert sort_third([4, 3, 2, 1]) == [1, 3, 2, 4]

def test_sort_third_five_elements_reorder_indices_0_and_3():
    assert sort_third([5, 4, 3, 2, 1]) == [2, 4, 3, 5, 1]

def test_sort_third_six_elements_reorder_indices_0_and_3():
    assert sort_third([6, 5, 4, 3, 2, 1]) == [3, 5, 4, 6, 2, 1]

def test_sort_third_with_negative_numbers():
    assert sort_third([-5, -4, -3, -2, -1]) == [-5, -4, -3, -2, -1]

def test_sort_third_with_floats():
    assert sort_third([3.5, 2.5, 1.5, 4.5]) == [1.5, 2.5, 3.5, 4.5]

def test_sort_third_with_strings():
    assert sort_third(['b', 'a', 'c', 'd', 'e', 'f']) == ['b', 'a', 'c', 'd', 'e', 'f']

def test_sort_third_maintains_input_immutability():
    original = [7, 8, 9, 10]
    copy = original[:]
    sort_third(original)
    assert original == copy

def test_sort_third_tuple_input_returns_list():
    result = sort_third((1, 2, 3, 4))
    assert isinstance(result, list)
    assert result == [1, 2, 3, 4]

def test_sort_third_generator_input():
    gen = (i for i in [1, 2, 3, 4, 5, 6])
    result = sort_third(gen)
    assert result == [1, 2, 3, 4, 5, 6]

def test_sort_third_string_input():
    result = sort_third("abcd")
    assert result == ['a', 'b', 'c', 'd']

def test_sort_third_unsortable_slice_raises_type_error():
    with pytest.raises(TypeError):
        sort_third([1, 'a', 3, 'b', 5, 'c'])

def test_sort_third_none_input_raises_type_error():
    with pytest.raises(TypeError):
        sort_third(None)

def test_sort_third_non_iterable_input_raises_type_error():
    with pytest.raises(TypeError):
        sort_third(42)

def test_sort_third_slice_with_mixed_comparable_types():
    result = sort_third([5, 4, 3, 2, 1])
    assert result == [2, 4, 3, 5, 1]

def test_sort_third_with_duplicate_values():
    assert sort_third([3, 1, 2, 3, 4, 1]) == [1, 1, 2, 3, 4, 3]

def test_sort_third_with_large_list_boundary():
    large = list(range(1000))
    expected = large[:]
    expected[::3] = sorted(expected[::3])
    assert sort_third(large) == expected

def test_sort_third_when_slice_length_one_no_change():
    assert sort_third([10]) == [10]

def test_sort_third_when_slice_length_zero_no_change():
    assert sort_third([1, 2]) == [1, 2]
